sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    //initialize Script Include
    var iawUpdateCase = new x_hsb11_iaw_widget.IAWUpdateCase();
    var resp;
    var switchValue;

    var tradeCase = current.sn_task.parent;
	var responseCode = current.response_code;

    try {
		var response = JSON.parse(current.response_body);
    } catch (err) {}
    var validCodes = gs.getProperty('x_hsb11_iaw_widget.iaw_widget_valid_codes');

    //Check if we have received a valid response code as per the System Property x_hsb11_iaw_widget.iaw_widget_valid_codes

    if (validCodes.indexOf(current.response_code) == -1) {
        // Calls the rest message configured to send widget failure details to ITID instance and creates an Event
        try {
            var failureDescription = "Cash Equities IAW Outbound Widget failure, details of the error are as below ServiceNow Reference: " + current.sn_task.number +" Timestamp : " + current.response_date + " Error code: " + current.response_code + " Error Body: " + current.response_body; //MSSOTIQUBE-1358
            var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_IAW');
        } catch (err) {} finally {
            //set switchValue to Error so that we can update the Trade Case
            switchValue = 'ERROR';
        }
    } else {
        //take the switch value from Request Type if not an Error
        switchValue = current.request_type.toString();
    }

    //Call the IAWUpdateCase Script Include to update the parent Case
    switch (switchValue) {

        case 'CUH':
            resp = iawUpdateCase.cuh_update(tradeCase, response);
            break;
        case 'ALMH':
            resp = iawUpdateCase.almh_update(tradeCase, response);
            break;
        case 'MAIH':
            resp = iawUpdateCase.maih_update(tradeCase, response, responseCode);  //we need to pass response code to MAIH to choose the right outcome
            break;
        case 'FCIH':
            resp = iawUpdateCase.fcih_update(tradeCase, response);
            break;
        case 'BTMH':
            resp = iawUpdateCase.btmh_update(tradeCase, response);
            break;
        case 'ERROR':
            resp = iawUpdateCase.error_update(tradeCase, response);
            break;
    }


    //If we have an 'ERROR' response, cancel the Trade Task and create a new MOCS Task for investigation
    if (resp == 'ERROR') {
		updateTradeTask(current.getValue('sn_task'), 7, resp); //set the Trade Task to 'Cancelled'
		createMOCSTradeTask();
    } else {
		updateTradeTask(current.getValue('sn_task'), 3, resp); //set the Trade Task to 'Closed Complete'
	}


    function updateTradeTask(taskSysId, stateValue, closeNotes) {

        var grTradeTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        grTradeTask.addQuery('sys_id', taskSysId);
        grTradeTask.query();
        if (grTradeTask.next()) {
            grTradeTask.setValue('state', stateValue);
            grTradeTask.setValue('close_notes', 'IAW Response: ' + closeNotes);
            grTradeTask.update();

        }

    }

    //Create a task for MOCS to investigate
    function createMOCSTradeTask() {
        var grTradeTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
        grTradeTask.addQuery("number", current.sn_task.number);
        grTradeTask.query();
        if (grTradeTask.next()) {

            //fetching the sn task id and short description of the previous task
            var pTaskId = grTradeTask.number;
            var pShortDesc = grTradeTask.short_description;

			//creating new task for MOCS
			var grNewTradeTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
            grNewTradeTask.initialize();
            grNewTradeTask.setValue('parent', tradeCase);
            grNewTradeTask.setValue('assignment_group', gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs"));
            grNewTradeTask.short_description = pTaskId + " for " + pShortDesc + " " + gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.short.description.mocs");
            grNewTradeTask.setValue('description', decodeURIComponent(failureDescription) + '\n\n' + gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.description.mocs"));
            grNewTradeTask.insert();
        }
    }
})(current, previous);
